// parseDuration("1h30m") -> 5400000

const UNIT_MS = {
  ms: 1,
  s: 1000,
  m: 60 * 1000,
  h: 60 * 60 * 1000,
  d: 24 * 60 * 60 * 1000,
  w: 7 * 24 * 60 * 60 * 1000,
};

// One "<number><unit>" pair, e.g. "1h" or "1.5s". "ms" comes first so it wins over "m".
const PART = /(\d+(?:\.\d+)?)\s*(ms|s|m|h|d|w)/gy;

export function parseDuration(input) {
  if (typeof input !== "string") {
    throw new TypeError(`parseDuration expected a string, got ${typeof input}`);
  }

  const trimmed = input.trim();
  if (trimmed === "") {
    throw new Error("parseDuration received an empty string");
  }

  const signed = /^[+-]/.test(trimmed);
  const sign = trimmed.startsWith("-") ? -1 : 1;
  const body = signed ? trimmed.slice(1).trim() : trimmed;

  // A bare number is treated as milliseconds.
  if (/^\d+(?:\.\d+)?$/.test(body)) {
    return sign * Number(body);
  }

  let total = 0;
  let matched = false;
  PART.lastIndex = 0;

  while (PART.lastIndex < body.length) {
    const match = PART.exec(body);
    if (!match) {
      throw new Error(`Invalid duration: ${JSON.stringify(input)}`);
    }
    total += Number(match[1]) * UNIT_MS[match[2]];
    matched = true;

    // Allow whitespace between parts, e.g. "1h 30m".
    while (body[PART.lastIndex] === " " || body[PART.lastIndex] === "\t") {
      PART.lastIndex++;
    }
  }

  if (!matched) {
    throw new Error(`Invalid duration: ${JSON.stringify(input)}`);
  }

  return sign * total;
}
EOF
cat > duration.test.js <<'EOF'
import { expect, test } from "bun:test";
import { parseDuration } from "./duration.js";

test("parses a single unit", () => {
  expect(parseDuration("45s")).toBe(45000);
  expect(parseDuration("500ms")).toBe(500);
  expect(parseDuration("2m")).toBe(120000);
  expect(parseDuration("3h")).toBe(10800000);
  expect(parseDuration("1d")).toBe(86400000);
  expect(parseDuration("1w")).toBe(604800000);
});

test("parses compound durations", () => {
  expect(parseDuration("1h30m")).toBe(5400000);
  expect(parseDuration("1h30m15s")).toBe(5415000);
  expect(parseDuration("2d4h")).toBe(187200000);
  expect(parseDuration("1m500ms")).toBe(60500);
});

test("distinguishes m from ms", () => {
  expect(parseDuration("1m")).toBe(60000);
  expect(parseDuration("1ms")).toBe(1);
  expect(parseDuration("1m1ms")).toBe(60001);
});

test("allows whitespace between and inside parts", () => {
  expect(parseDuration("1h 30m")).toBe(5400000);
  expect(parseDuration("  1h30m  ")).toBe(5400000);
  expect(parseDuration("1 h 30 m")).toBe(5400000);
});

test("supports decimals", () => {
  expect(parseDuration("1.5h")).toBe(5400000);
  expect(parseDuration("0.5s")).toBe(500);
});

test("supports signs", () => {
  expect(parseDuration("-1h30m")).toBe(-5400000);
  expect(parseDuration("+45s")).toBe(45000);
});

test("treats a bare number as milliseconds", () => {
  expect(parseDuration("250")).toBe(250);
  expect(parseDuration("0")).toBe(0);
});

test("repeated units accumulate", () => {
  expect(parseDuration("30m30m")).toBe(3600000);
});

test("rejects invalid input", () => {
  expect(() => parseDuration("")).toThrow();
  expect(() => parseDuration("   ")).toThrow();
  expect(() => parseDuration("abc")).toThrow();
  expect(() => parseDuration("1y")).toThrow();
  expect(() => parseDuration("1h30")).toThrow();
  expect(() => parseDuration("h30m")).toThrow();
  expect(() => parseDuration("1h-30m")).toThrow();
  expect(() => parseDuration(90)).toThrow(TypeError);
  expect(() => parseDuration(null)).toThrow(TypeError);
});
EOF
